import{_ as g}from"./chunks/image1.Bk1JI49V.js";import{_ as o}from"./chunks/image2.UYnXny4D.js";import{_ as r}from"./chunks/image3.z0vX6Nw7.js";import{_ as n}from"./chunks/image4.Co4Tm3RS.js";import{_ as s}from"./chunks/image5.NlMtFgFW.js";import{_ as p,c as l,o as a,ae as e}from"./chunks/framework.B8KKhRA6.js";const T=JSON.parse('{"title":"4-4. 장기재직자 재충전휴가 사용지침","description":"","frontmatter":{"title":"4-4. 장기재직자 재충전휴가 사용지침"},"headers":[],"relativePath":"manual/4-4._장기재직자_재충전휴가_사용지침.md","filePath":"manual/4-4._장기재직자_재충전휴가_사용지침.md"}'),i={name:"manual/4-4._장기재직자_재충전휴가_사용지침.md"};function u(c,t,_,h,q,b){return a(),l("div",null,t[0]||(t[0]=[e('<blockquote><p>&quot;문화와 예술로 행복한 서울 만들기&quot;</p></blockquote><p>+-------------------+--------------------------------------------------+ | &gt; 문서번호 | &gt; 인사팀-715 | +:=================:+==================================================+ | &gt; 보존기간 | &gt; 준영구 | +-------------------+--------------------------------------------------+ | &gt; 결재일자 | &gt; 2024. 03. 04. | +-------------------+--------------------------------------------------+ | &gt; 공개여부 | &gt; 공개 | +-------------------+--------------------------------------------------+ | &gt; 방침번호 | &gt; 대표이사 방침 제(112)호 | +-------------------+--------------------------------------------------+</p><p>+---------------------------------------------------------------------------------------------------------------+----------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------------------------------------------------------------------+--------------------------------------------------------------------------------------------------------------+ | &gt; ★사원 | &gt; 팀장 | &gt; 본부장 | &gt; 대표이사 | :============================================================================================================:+ | &gt; <img src="'+g+'" alt="" width="0.42205161854768153in" height="0.125in"> | &gt; <img src="'+o+'" alt="" width="0.4095909886264217in" height="0.11666557305336833in"> | &gt; <img src="'+r+'" alt="" width="0.4229658792650919in" height="0.125in"> | &gt; <strong>03/04</strong> | | | | | &gt; | | | | | &gt; <img src="'+n+'" alt="" width="0.4065540244969379in" height="0.125in"> | +---------------------------------------------------------------------------------------------------------------+----------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------------------------------------------------------------------+--------------------------------------------------------------------------------------------------------------+ | &gt; 협 조 | | +---------------------------------------------------------------------------------------------------------------+----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+ | | +--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+</p><blockquote><p><strong>서울문화재단 장기재직자 재충전휴가 사용지침 개정</strong></p></blockquote><p><img src="'+s+'" alt="" width="3.457171916010499in" height="0.7046872265966754in"></p><blockquote><p><strong>서울문화재단 장기재직자 재충전휴가 사용지침 개정</strong></p><p><strong>「서울문화재단 복무규정」및「서울특별시 공무원 휴가 등 업무지침(2024.2.7.)에 근거하여 서울문화재단 장기재직자 재충전휴가 사용과 관련한 세부 운영지침을 마련 하여 운영하고자 함</strong></p></blockquote><h1 id="추진근거" tabindex="-1">추진근거 <a class="header-anchor" href="#추진근거" aria-label="Permalink to &quot;추진근거&quot;">​</a></h1><blockquote><p><strong>□</strong> 서울문화재단 복무규정 제30조의2(특별휴가) 제1항</p><p>Ⅰ</p><p><strong>제30조의2(특별휴가)</strong> ① 대표이사는 재직기간이 5년 이상 10년 미만인 직원에게 해당 재직 기간 중 5일, 10년 이상 20년 미만인 직원에게 해당 재직기간 중 15일, 20년 이상 30년</p><p>미만 및 30년 이상 재직한 직원에게는 해당 재직기간 중 각각 25일의 휴가를 허가할 수 있으며, 운영에 필요한 사항은 대표이사가 따로 정한다. &lt;개정 2023. 09. 26.&gt;</p></blockquote><ul><li>서울특별시 공무원 휴가 등 업무지침(2024.2.7.)</li></ul><blockquote><p>장기재직휴가는 주기 내 분할하여 실시할 수 있으며, 업무, 개인의 사정에 따라 25일인 경우 5회로, 15일의 경우 3회로 나누어 주기 내 사용이 가능하며, 필요 시 주기에 부여된 휴가를 같은 해에 모두 사용할 수 있음</p><p><strong>□</strong> 대표이사 방침 제309(인사팀-2975, 2023.10.19.)호 &quot;서울문화재단 장기재직자 재충전휴가 사용지침 개정&quot;</p></blockquote><h1 id="주요-개선사항" tabindex="-1">주요 개선사항 <a class="header-anchor" href="#주요-개선사항" aria-label="Permalink to &quot;주요 개선사항&quot;">​</a></h1><p><strong>개선 후</strong></p><blockquote><p><strong>▶</strong></p><p>Ⅱ</p></blockquote><p>+-------------------------------+-----------------+----------------------+ | &gt; <strong>구 분</strong> | &gt; <strong>휴가 일수</strong> | &gt; <strong>비 고</strong> | +:=============================:+:===============:+======================+ | &gt; 30년 이상 | &gt; 25 | &gt; 분할사용 불가 | +-------------------------------+-----------------+ | | &gt; 20년 이상 | &gt; 25 | | | &gt; | | | | &gt; 30년 미만 | | | +-------------------------------+-----------------+ | | &gt; 10년 이상 | &gt; 15 | | | &gt; | | | | &gt; 20년 미만 | | | +-------------------------------+-----------------+ | | &gt; 5년 이상 | &gt; 5 | | | &gt; | | | | &gt; 10년 미만 | | | +-------------------------------+-----------------+----------------------+</p><p>+--------------------------+----------------------------------------------+ | &gt; <strong>구 분</strong> | <strong>기존</strong> | +==========================+==============================================+ | &gt; <strong>휴가 분할사용 허가</strong> | | +--------------------------+----------------------------------------------+</p><p>+---------------------------+-----------------+------------+---------------+ | &gt; <strong>구 분</strong> | &gt; <strong>휴가 일수</strong> | &gt; <strong>최대</strong> | &gt; <strong>비 고</strong> | | | | &gt; | | | | | &gt; <strong>사용</strong> | | | | | &gt; | | | | | &gt; <strong>횟수</strong> | | +:=========================:+:===============:+:==========:+===============+ | &gt; 30년 이상 | &gt; 25 | &gt; 5 | | +---------------------------+-----------------+------------+---------------+ | &gt; 20년 이상 | &gt; 25 | &gt; 5 | | | &gt; | | | | | &gt; 30년 미만 | | | | +---------------------------+-----------------+------------+---------------+ | &gt; 10년 이상 | &gt; 15 | &gt; 3 | | | &gt; | | | | | &gt; 20년 미만 | | | | +---------------------------+-----------------+------------+---------------+ | &gt; 5년 이상 | &gt; 5 | &gt; 1 | 분할사용 | | &gt; | | | | | &gt; 10년 미만 | | | 불가 | +---------------------------+-----------------+------------+---------------+</p><p>+------------------------------------------------+------------------------------------------------------------------------------+--------------------------------------------------------------------+ | &gt; <strong>연도 중 기간도래자의 사용 기한 연장</strong> | &gt; 입사일로부터 재직기간 산정하여 해당 구분연수 중 사용 원칙 (미사용 시 소멸) | &gt; 연도 중 기간 도래자의 경우, | | | | &gt; | | | | &gt; <strong>▶</strong> 해당연도 말일까지 사용 기한 연장 | | | | &gt; | | | | &gt; (미사용 시 소멸) | | | | &gt; | | | | &gt; ▼ | | | | &gt; | | | | &gt; <strong>▶</strong> &#39;장기재직자 휴가 재충전휴가 시작일로부터 | | | | &gt; | | | | &gt; 계획&#39; 기안 3일 전 | | | | &gt; | | | | &gt; ▼ 근무상황부 | | | | &gt; | | | | &gt; 시행 시점 전 | | | | &gt; | | | | &gt; 상신 | | | | &gt; | | | | &gt; <strong>1) 팀장, 매니저 및 팀원</strong> 기안자&gt;부서장(검토)&gt;복무담당(협조) | | | | &gt; | | | | &gt; &gt;실장(검토)&gt;본부장(전결) | | | | &gt; | | | | &gt; ※ 본부장 없는 부서는 실장(전결) | | | | &gt; | | | | &gt; <strong>▶ 2) 실장</strong> | | | | &gt; | | | | &gt; 기안자&gt;본부장(검토)&gt;복무담당(협조) | | | | &gt; | | | | &gt; &gt;대표이사(결재) | | | | &gt; | | | | &gt; <strong>3) 본부장 및 전문위원</strong> 기안자&gt;복무담당(협조)&gt;대표이사(결재) | | | | &gt; | | | | &gt; <strong>▶</strong> | +-----------------------+------------------------+------------------------------------------------------------------------------+ | | &gt; <strong>사용절차 간소화</strong> | &gt; <strong>신청 기한 완화</strong> | &gt; ▼ | | | | | &gt; | | | | | &gt; &#39;장기재직자 휴가 재충전휴가 시작일로부터 계획&#39; 기안 일주일 전 | | | | | &gt; | | | | | &gt; ▼ 근무상황부 | | | | | &gt; | | | | | &gt; 시행 시점 전 | | | | | &gt; | | | | | &gt; 상신 | | | +------------------------+------------------------------------------------------------------------------+ | | | &gt; <strong>결재 라인 간소화</strong> | &gt; 기안자&gt;부서장(검토) | | | | | &gt; | | | | | &gt; &gt;복무담당(협조)&gt;인사팀장(협조) | | | | | &gt; | | | | | &gt; &gt;실/본부장(검토) | | | | | &gt; | | | | | &gt; &gt;대표이사(결재) | | +-----------------------+------------------------+------------------------------------------------------------------------------+ | | &gt; <strong>분할사용에 따른 신청양식 개선</strong> | &gt; (신 규) | | +=======================+========================+==============================================================================+====================================================================+</p><p>+-------------------------------+--------------------------------------+ | &gt; <strong>구 분</strong> | &gt; <strong>기 한</strong> | +===============================+:====================================:+ | &gt; 부서장 협의 | &gt; 휴가 시작일로부터 | | | &gt; | | | &gt; 1개월 전 | +-------------------------------+--------------------------------------+</p><p>+-------------------------------+--------------------------------------+ | &gt; <strong>구 분</strong> | &gt; <strong>기 한</strong> | +===============================+:====================================:+ | &gt; 부서장 협의 | &gt; 휴가 | | | &gt; | | | &gt; 시작일로부터 일주일 전 | +-------------------------------+--------------------------------------+</p><hr><hr><hr><hr><hr><hr><hr><hr><h1 id="시행원칙-및-절차" tabindex="-1">시행원칙 및 절차 <a class="header-anchor" href="#시행원칙-및-절차" aria-label="Permalink to &quot;시행원칙 및 절차&quot;">​</a></h1><h2 id="시행원칙" tabindex="-1">시행원칙 <a class="header-anchor" href="#시행원칙" aria-label="Permalink to &quot;시행원칙&quot;">​</a></h2><blockquote><p>Ⅲ</p><p><strong>ㅇ 업무공백 방지를 위해 부서장과 사전 협의</strong></p><p><strong>ㅇ 휴가는 한 번에 사용하는 것이 원칙이나 기준에 따라 분할사용 가능 ㅇ 축제, 행정사무감사, 경영평가 등 부서 주요업무 추진기간 중 휴가 자제 ㅇ 휴가로 인한 업무공백이 발생하지 않도록 대직자 지정과 업무 인수인계 철저</strong></p></blockquote><h2 id="시행절차" tabindex="-1">시행절차 <a class="header-anchor" href="#시행절차" aria-label="Permalink to &quot;시행절차&quot;">​</a></h2><p>+---------------+-------------------------------+------------------------------------------------+ | &gt; <strong>구 분</strong> | &gt; <strong>기 한</strong> | &gt; <strong>내 용</strong> | +===============+===============================+================================================+ | &gt; 부서장 협의 | &gt; 휴가 시작일로부터 일주일 전 | - 재충전휴가 계획을 부서장과 협의 | | | | | | | | - 업무에 지장이 없는 범위 내에서 휴가기간 선정 | +---------------+-------------------------------+------------------------------------------------+</p><blockquote><p>▼</p></blockquote><p>+------------------------+---------------------------------------------------+ | &gt; 팀장, 매니저 및 팀원 | &gt; 기안자&gt;부서장(검토)&gt;복무담당(협조) | | | &gt; | | | &gt; &gt;실장(검토)&gt;본부장(전결) | | | &gt; | | | &gt; ※ 본부장 없는 부서는 실장(전결) | +========================+===================================================+ | &gt; 실장 | &gt; 기안자&gt;본부장(검토)&gt;복무담당(협조) | | | &gt; | | | &gt; &gt;대표이사(결재) | +------------------------+---------------------------------------------------+ | &gt; 본부장 및 전문위원 | &gt; 기안자&gt;복무담당(협조)&gt;대표이사(결재) | +------------------------+---------------------------------------------------+</p><p>+-------------------------------------+----------------------------+-----------------------------------------+ | &gt; &#39;장기재직자 재충전휴가 계획&#39; 기안 | &gt; 휴가 시작일로부터 3일 전 | - 휴가계획서(붙임 2)를 작성하여 기안 | | | | | | | | - 결재라인 | +=====================================+============================+=========================================+</p><blockquote><p>▼</p></blockquote><p>+-------------------+----------------+----------------------------------------------------+ | &gt; 근무상황부 상신 | &gt; 시행 시점 전 | &gt; - 더존iU&gt;근무상황부&gt;장기재직자재충전휴가 상신 | | | | &gt; | | | | &gt; ※ 결재라인: 부서장(전결) | +===================+================+====================================================+</p><h2 id="재직기간별-휴가일수-및-신청방법" tabindex="-1">재직기간별 휴가일수 및 신청방법 <a class="header-anchor" href="#재직기간별-휴가일수-및-신청방법" aria-label="Permalink to &quot;재직기간별 휴가일수 및 신청방법&quot;">​</a></h2><blockquote><p><strong>ㅇ 휴가일수 및 분할사용 방법</strong></p></blockquote><p>+-----------------------+---------------+---------------------+------------------+ | &gt; <strong>구 분</strong> | <strong>휴가일수</strong> | &gt; <strong>최대 사용횟수</strong> | <strong>비 고</strong> | +:=====================:+:=============:+:===================:+==================+ | &gt; 30년 이상 | 25 | 5 | | +-----------------------+---------------+---------------------+------------------+ | &gt; 20년 이상 30년 미만 | 25 | 5 | | +-----------------------+---------------+---------------------+------------------+ | &gt; 10년 이상 20년 미만 | 15 | 3 | | +-----------------------+---------------+---------------------+------------------+ | &gt; 5년 이상 10년 미만 | 5 | 1 | 분할사용 불가 | +-----------------------+---------------+---------------------+------------------+</p><blockquote><p>- 휴가는 한 번에 사용하는 것이 원칙이나 상기 기준에 따라 분할사용 가능</p><p>- <strong>1회당 최소 5일 이상</strong> 사용해야 하나 잔여일수가 5일 미만의 경우 잔여일수만큼</p><p>사용 가능</p><p>【예시1】15일 : 15일 모두 사용 또는 5+7+3, 6+6+3 등의 방법으로 실시</p><p>【예시2】25일 : 10+15일, 5+5+15, 5+5+5+5+5일 등의 방법으로 실시</p></blockquote><ul><li>장기재직자 재충전휴가는 오랜 기간 사용이(5~10년) 가능하므로, 구분연수 내 사용해야 하며 이월 불가</li></ul><blockquote><p><strong>ㅇ 연도 중 기간 도래자의 경우</strong></p></blockquote><ul><li>연도 중 기간 도래자의 경우, 해당연도 말일까지 사용 가능</li></ul><blockquote><p>【예시】입사일자가 2004.3.15인 직원의 경우</p></blockquote><p>+-----------------------+----------------+------------------------------+ | &gt; <strong>구분</strong> | <strong>휴가일수</strong> | <strong>사용기한</strong> | +:=====================:+:==============:+:============================:+ | &gt; 10년 이상 19년 미만 | 15 | 2024.12.31까지 사용 가능 | +-----------------------+----------------+------------------------------+ | &gt; 20년 이상 30년 미만 | 25 | 2024.3.15부터 사용 가능 | +-----------------------+----------------+------------------------------+</p><blockquote><p><strong>→</strong> 입사일자가 2004.3.15인 직원의 경우, 2024.3.15자로 재직기간이 20년이 도래하여도 2024.12.31까지는 19년차 장기재직자 재충전휴가 사용 가능</p></blockquote><h1 id="휴가-시-유의사항" tabindex="-1">휴가 시 유의사항 <a class="header-anchor" href="#휴가-시-유의사항" aria-label="Permalink to &quot;휴가 시 유의사항&quot;">​</a></h1><ul><li>상위 직급자가 재충전휴가를 적극 사용하여 직원들이 휴가를 사용할 수 있는 자연스러운 분위기 조성</li></ul><blockquote><p>Ⅴ</p></blockquote><ul><li><p>휴가 중 긴급 연락이 가능하도록 비상연락체계 반드시 유지</p></li><li><p>휴가자 담당업무를 대직자에게 인계하여 업무 연속성 유지</p></li><li><p>대내/외 협조기관 및 부서와 사전 소통</p></li><li><p>연1회 실태조사를 통하여, 휴가일수 초과사용 시 연차 공제 예정</p></li><li><p>재충전 효과의 극대화를 위해 연차와 연계사용 가능</p></li></ul><blockquote><p><strong>ㅇ 장기재직자 재충전휴가와 별도로 연차 상신 필요</strong></p><p><strong>관련문서 1. 대표이사 방침 제 309(인사팀-2975, 2023.10.19.)호</strong></p><p><strong>&quot;서울문화재단 장기재직자 재충전휴가 사용지침 개정&quot; 1부.</strong></p><p><strong>붙임문서 1. 서울문화재단 복무규정 1부.</strong></p></blockquote><ol start="2"><li><p><strong>2024년 서울특별시 공무원 휴가 등 업무지침(2024.2.7.).</strong></p></li><li><p><strong>휴가계획서 양식 1부. 끝.</strong></p></li></ol>',53)]))}const w=p(i,[["render",u]]);export{T as __pageData,w as default};
